 (function () {
    function addOrRemoveBanner() {
        let quote;
        try {
            quote = JSON.parse(sessionStorage.getItem("quote") || "{}");
        } catch (e) {
            return;
        }
        const target = document.querySelector(
            ".jsx-1078939948.inner-container.md\\:mt-6.mt-0"
        );
        if (!target) return;
        // Inject CSS only once
        if (!document.querySelector("#salary-day-style")) {
            const style = document.createElement("style");
            style.id = "salary-day-style";
            style.innerHTML = `
/* Desktop */
#salary-day-eyebrow-vwo{
    width:100%;
    display:flex;
    justify-content:center;
    transform:translateY(20%);
    margin-bottom:-10px;
    position:relative;
    z-index:5;
}
#salary-day-eyebrow-vwo .salary-day-wrapper{
    display:flex;
    align-items:center;
    justify-content:center;
    gap:18px;
    background:#fff;
    padding:0 18px;
}
#salary-day-eyebrow-vwo .salary-line{
    width:80px;
    height:1px;
    background:linear-gradient(to right, transparent, #B41F66, transparent);
    flex-shrink:0;
}
#salary-day-eyebrow-vwo .salary-text{
    font-family:Lato,sans-serif;
    font-size:14px;
    font-weight:600;
    color:#171A21;
    line-height:1.35;
    white-space:nowrap;
}
#salary-day-eyebrow-vwo .salary-text strong{
    color:#A61D5D;
    font-weight:700;
}
/* Mobile */
@media (max-width:768px){
    #salary-day-eyebrow-vwo{
        transform:translateY(-20%);
        margin-bottom:-6px;
        padding:0 6px;
    }
    #salary-day-eyebrow-vwo .salary-day-wrapper{
        gap:4px;
        padding:0 4px;
    }
    #salary-day-eyebrow-vwo .salary-line{
        width:15px;
    }
    #salary-day-eyebrow-vwo .salary-text{
        font-family:Lato,sans-serif;
        font-size:12px;
        font-weight:600;
        line-height:1.2;
        white-space:nowrap;
        text-align:center;
    }
    #salary-day-eyebrow-vwo .salary-text strong{
        font-size:12px;
        font-weight:700;
    }
}
            `;
            document.head.appendChild(style);
        }
        const existingBanner = target.querySelector("#salary-day-eyebrow-vwo");
        // Remove banner if occupation is not salaried
        if (quote.occupation !== "salaried") {
            if (existingBanner) {
                existingBanner.remove();
            }
            return;
        }
        // Add banner only if it doesn't already exist
        if (!existingBanner) {
            const banner = document.createElement("div");
            banner.id = "salary-day-eyebrow-vwo";
            banner.innerHTML = `
                <div class="salary-day-wrapper">
                    <span class="salary-line"></span>
                    <span class="salary-text">
                        This Salary Day, Make one impulse purchase
                        <strong>you'll never regret</strong>
                    </span>
                    <span class="salary-line"></span>
                </div>
            `;
            target.prepend(banner);
        }
    }
    // Initial execution
    addOrRemoveBanner();
    // Keep checking because the popup re-renders
    setInterval(addOrRemoveBanner, 300);
})(); 
